<script>
function showTab(tabName){document.querySelectorAll('.tab-panel').forEach(panel=>panel.classList.add('hidden'));document.querySelectorAll('.tab-button').forEach(button=>{button.classList.remove('active','text-red-600','border-red-600');button.classList.add('text-gray-500','border-transparent');});document.getElementById(`panel-${tabName}`).classList.remove('hidden');const activeTab=document.getElementById(`tab-${tabName}`);activeTab.classList.add('active','text-red-600','border-red-600');activeTab.classList.remove('text-gray-500','border-transparent');}
const urlParams=new URLSearchParams(window.location.search);const tab=urlParams.get('tab');if(tab)showTab(tab);
</script>
